from ortools.sat.python import cp_model

baristas = ["Ana", "Ben", "Chen", "Dara", "Eli", "Fay"]
wage = {"Ana": 18, "Ben": 16, "Chen": 17, "Dara": 19, "Eli": 16, "Fay": 18}
days = ["Mon", "Tue", "Wed", "Thu", "Fri"]
shifts = [(d, blk) for d in days for blk in ["open", "mid", "close"]]
need = {"open": 2, "mid": 1, "close": 2}

model = cp_model.CpModel()
assign = {(b, s): model.NewBoolVar(f"{b}_{s[0]}_{s[1]}")
          for b in baristas for s in shifts}

# Cover every shift block
for s in shifts:
    model.Add(sum(assign[b, s] for b in baristas) >= need[s[1]])
# Max 5 shifts per barista per week
for b in baristas:
    model.Add(sum(assign[b, s] for s in shifts) <= 5)
# No close-then-open ("clopen") back to back
for b in baristas:
    for d1, d2 in zip(days, days[1:]):
        model.AddBoolOr([assign[b, (d1, "close")].Not(),
                         assign[b, (d2, "open")].Not()])

model.Minimize(sum(wage[b] * 4 * assign[b, s]  # 4-hour blocks
                   for b in baristas for s in shifts))

solver = cp_model.CpSolver()
status = solver.Solve(model)
print(solver.StatusName(status), f"| weekly labor cost ${solver.ObjectiveValue():,.0f}")
for s in shifts:
    crew = [b for b in baristas if solver.Value(assign[b, s])]
    print(f"{s[0]} {s[1]:>5}: {', '.join(crew)}")
